#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    // If no numbers are provided, the original program prints "EMPTY".
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    // The original binary stores at most 64 numbers.
    long values[64];
    int count = 0;
    for (int i = 1; i < argc && count < 64; ++i) {
        char *endptr;
        long v = strtol(argv[i], &endptr, 10);
        // The original code does not check for conversion errors, so we store the result directly.
        (void)endptr; // suppress unused warning
        values[count++] = v;
    }

    // The original program builds a sorted linked list in a stable manner (duplicates keep input order).
    // A stable insertion sort reproduces the same ordering.
    for (int i = 1; i < count; ++i) {
        long key = values[i];
        int j = i - 1;
        while (j >= 0 && values[j] > key) {
            values[j + 1] = values[j];
            --j;
        }
        values[j + 1] = key;
    }

    // Print the numbers separated by a single space, then a newline.
    for (int i = 0; i < count; ++i) {
        if (i) putchar(' ');
        printf("%ld", values[i]);
    }
    putchar('\n');
    return 0;
}
